# ─────────────────────────────────────────────────────────────


def main():
    try:
        sys.stdout.reconfigure(encoding='utf-8')  # cp949 콘솔에서도 출력 안전(em-dash 등)
    except Exception:
        pass
    dry = '--dry' in sys.argv
    if not os.path.exists(PATH):
        print('!! 파일 없음:', PATH)
        return 2

    text = io.open(PATH, encoding='utf-8-sig').read()
    orig_len = len(text)

    print('========== 치환 적용 건수 ==========')
    fails = []
    for i, (before, after) in enumerate(SUBS, 1):
        n = text.count(before)
        head = before[:56].replace('\n', ' ')
        print('  [%02d] %d건  | %s%s' % (i, n, head, '…' if len(before) > 56 else ''))
        if n == 0:
            fails.append(i)
            continue
        if n > 1:
            print('       ^^ 주의: %d곳에 매치됨 — 전부 치환됨' % n)
        text = text.replace(before, after)

    print()
    if fails:
        print('!! 0건 치환 %d개: %s' % (len(fails), fails))
        # ── 드리프트 지점 진단(2026-07-31 추가, 성공 경로에는 영향 없음) ──
        #   before 문자열 중 "원문에 실제로 존재하는 최장 접두"를 이분 탐색으로 찾아,
        #   어디서부터 어긋나는지 보여준다. (before 전체를 눈으로 대조하지 않아도 됨)
        for i in fails:
            b = SUBS[i - 1][0]
            lo, hi = 0, len(b)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if b[:mid] in text:
                    lo = mid
                else:
                    hi = mid - 1
            print('  [%02d] 원문 일치 접두 %d/%d자 — 이 지점부터 어긋남:' % (i, lo, len(b)))
            print('       OK …%s' % b[max(0, lo - 40):lo].replace('\n', ' '))
            print('       ✗  %s…' % b[lo:lo + 60].replace('\n', ' '))
        print('!! 원문이 외부에서 변경되었을 수 있음 → **아무것도 쓰지 않고 중단**.')
        print('!! 해당 before 문자열을 현재 원문과 대조해 갱신할 것.')
        return 1

    if dry:
        print('(--dry) 검증만 수행 — 파일 미변경. bytes %d -> %d 예상'
              % (orig_len, len(text)))
        return 0

    with io.open(PATH, 'w', encoding='utf-8', newline='') as f:
        f.write(text)
    print('RESULT: OK — %d개 치환 완료, 파일 갱신됨.' % len(SUBS))
    print('  chars %d -> %d' % (orig_len, len(text)))
    return 0


if __name__ == '__main__':
    sys.exit(main())
